const state={availability:[],slots:[],assignments:{},memberStatuses:{},memberStores:{},memberWants:{},memberDislikes:{},memberDrips:{},memberCars:{},slotTypes:{},slotCounts:{},slotBlanks:{},settings:{},roleRequirements:{},gridDate:'',gridStore:'',gridMode:'role',countDate:'',fullNames:false,availDate:'',memberQuery:'',memberStore:'',view:'import'};
const rolesByStore={
  '本店':[['マスター',1],['レジ',1],['豆屋',1],['ドリッパー',6],['リベロ',3],['提供',2],['ホール',2]],
  '2号店':[['レジ',1],['調理',2]],
  'くれあ':[['レジ',1],['調理',1]]
};
const eventDayRoles={'2026-10-30':{'準備':[['店舗準備（本店）',10],['店舗準備（2号店）',5],['店舗準備（くれあ）',5],['実委からの受け取り',3],['買い出し',2],['昼食',0],['休憩',0],['最終オペ練',0]]}};
const roleStore={'店舗準備（本店）':'本店','店舗準備（2号店）':'2号店','店舗準備（くれあ）':'くれあ'};
