const availExtra={};// 勤務可能表に手で追加したメンバー（日付ごと。○を付けるまではこの画面だけ）
function renderAvailabilityBoard(){const board=$('#availabilityBoard'),dates=eventDates();if(!dates.length){board.innerHTML='';$('#availDates').innerHTML='';return;}if(!dates.includes(state.availDate))state.availDate=dates[0];const peopleOn=date=>[...new Set(state.availability.filter(a=>a.date===date).map(a=>a.name))];$('#availDates').innerHTML=segHtml(dates.map((date,i)=>({value:date,label:dayName(date,i),sub:shortDay(date),badge:`${peopleOn(date).length}名`})),state.availDate,'data-avail-date');const date=state.availDate,entries=state.availability.filter(a=>a.date===date),hours=hoursForDate(date),names=[...new Set([...peopleOn(date),...(availExtra[date]||[])])].sort((a,b)=>a.localeCompare(b,'ja'));const can=(name,h)=>entries.some(a=>a.name===name&&a.start<=h&&a.end>=plusSlot(h));const all=[...new Set(state.availability.map(a=>a.name))].filter(n=>!names.includes(n)).sort((a,b)=>a.localeCompare(b,'ja'));board.innerHTML=`<div class="avail-tools"><span>セルをクリック（ドラッグでまとめて）すると ○／— を切り替えられます。ここを変えてもシフトの割当は外れません（勤務できない時間に入っている人は、シフト調整で色が付きます）。</span><form id="availAdd"><input id="availAddName" list="availAddList" placeholder="この日にメンバーを追加（名前）" autocomplete="off"><datalist id="availAddList">${all.map(n=>`<option value="${esc(n)}">`).join('')}</datalist><button class="quiet small">追加</button></form></div><div class="availability-wrap"><table class="availability-table editable"><thead><tr><th>スタッフ（${names.length}名）</th>${hours.map(h=>`<th>${h.endsWith(':00')?h:`<small>${h}</small>`}</th>`).join('')}</tr><tr class="count-row"><th>勤務可能人数</th>${hours.map(h=>`<th>${names.filter(n=>can(n,h)).length}人</th>`).join('')}</tr></thead><tbody>${names.map(name=>`<tr><td>${esc(name)}</td>${hours.map(h=>{const yes=can(name,h);return `<td class="${yes?'yes':'no'}${h.endsWith(':00')?' hour':''}" data-av-name="${esc(name)}" data-av-h="${h}">${yes?'○':'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
// 勤務可能時間を塗り替える：{name:{h:true/false}} を反映し、30分ごとの○をつなげて時間帯に戻す
function applyAvailability(date,changes){const before=state.availability.map(a=>({...a}));const toM=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};const next=state.availability.filter(a=>!(a.date===date&&changes[a.name]));for(const [name,cells] of Object.entries(changes)){const on=new Set();for(const a of state.availability)if(a.date===date&&a.name===name)for(let m=Math.floor(toM(a.start)/SLOT)*SLOT;m+SLOT<=toM(a.end);m+=SLOT)on.add(m);for(const [h,v] of Object.entries(cells)){if(v)on.add(toM(h));else on.delete(toM(h));}let run=null;for(const m of [...on].sort((a,b)=>a-b)){if(run&&m===run.end)run.end+=SLOT;else{if(run)next.push({name,date,start:toHM(run.start),end:toHM(run.end)});run={start:m,end:m+SLOT};}}if(run)next.push({name,date,start:toHM(run.start),end:toHM(run.end)});}state.availability=next;render();const after=JSON.stringify(state.availability);showToast('勤務可能時間を変更しました',false,{label:'元に戻す',fn:()=>{if(JSON.stringify(state.availability)!==after)return showToast('その後に変更があったため元に戻せません');state.availability=before;render();showToast('元に戻しました');}});}
