function hoursForDate(date){const entries=state.availability.filter(a=>a.date===date);if(!entries.length)return [];const min=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};const first=Math.floor(Math.min(...entries.map(a=>min(a.start)))/SLOT)*SLOT,last=Math.ceil(Math.max(...entries.map(a=>min(a.end)))/SLOT)*SLOT;return Array.from({length:Math.max(0,(last-first)/SLOT)},(_,i)=>toHM(first+i*SLOT));}
function ensureGridSlots(date,hours){for(const hour of hours){for(const [store,roles] of Object.entries(rolesForDate(date))){for(const [role,count] of roles){if(!state.slots.some(s=>s.date===date&&s.store===store&&s.role===role&&s.start===hour)){const id=slotId(date,store,role,hour);state.slots.push({id,date,store,role,start:hour,end:plusSlot(hour),count:state.slotCounts[id]??count});}}}}}
