const toMin=t=>Number(t.slice(0,2))*60+Number(t.slice(3));
function mergeSpans(items){const spans=[];for(const x of [...items].sort((a,b)=>a.start.localeCompare(b.start))){const last=spans[spans.length-1];if(last&&toMin(x.start)<=last.end)last.end=Math.max(last.end,toMin(x.end));else spans.push({start:toMin(x.start),end:toMin(x.end)});}return spans;}
function assignmentAudit(){const assigned=flattened().filter(item=>state.assignments[item.key]).map(item=>({...item,name:state.assignments[item.key]}));const conflicts=new Set(),hours={},booked={};for(const x of assigned)(booked[`${x.name}|${x.date}`]??=[]).push(x);for(const [id,items] of Object.entries(booked)){const [name,date]=id.split('|');for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++)if(items[j].start<items[i].end&&items[i].start<items[j].end){conflicts.add(items[i].key);conflicts.add(items[j].key);}const spans=mergeSpans(items.filter(x=>!breakRoles.includes(x.role)));(hours[name]??={})[date]=spans.reduce((sum,sp)=>sum+sp.end-sp.start,0)/60;}return {conflicts,hours,booked};}
