function carCellFor(date){if(!Object.values(state.memberCars).some(Boolean))return ()=>'';const busy=new Set(flattened().filter(x=>x.date===date&&state.assignments[x.key]).map(x=>`${state.assignments[x.key]}|${x.start}`));return h=>{const free=namesOn(date).filter(n=>state.memberCars[n]&&!busy.has(`${n}|${h}`));return `<span class="car ${free.length?'':'zero'}" title="${esc(free.length?`シフトに入っていない車持ち：${free.join('、')}`:'シフトに入っていない車持ちがいません')}">車${free.length}</span>`;};}
// 1日分のシフト表（行：時間、列：役職の各番目＝1セル1人）。ドリッパー2役職は通し番号（1〜6）
function dayGridHtml(date,storeF,audit){const hours=hoursForDate(date),carCell=carCellFor(date);const groups=Object.entries(rolesForDate(date)).filter(([store])=>!storeF||store===storeF);if(!groups.length)return '';const slotAt=new Map(state.slots.filter(s=>s.date===date).map(s=>[`${s.store}|${s.role}|${s.start}`,s]));const cols=[];for(const [store,roles] of groups)for(const [role,count] of roles){const max=Math.max(1,...hours.map(h=>Number(slotAt.get(`${store}|${role}|${h}`)?.count)||0)),base=roleBase(role),prev=cols[cols.length-1],same=prev&&prev.store===store&&prev.base===base;for(let i=0;i<max;i++){const p=cols[cols.length-1];cols.push({store,role,count,base,occ:i,num:(i||same)?p.num+1:1,gstart:i===0&&!same});}}const heads=[];for(const c of cols){const g=heads[heads.length-1];if(g&&g.store===c.store&&g.base===c.base)g.cols.push(c);else heads.push({store:c.store,base:c.base,role:c.role,count:c.count,cols:[c]});}const stores=groups.map(([store])=>[store,cols.filter(c=>c.store===store).length]);const headLabel=g=>g.base==='ドリッパー'?'ドリッパー':roleHeadHtml(g.role);return `<table class="shift-grid day split" style="min-width:${56+cols.length*100}px"><colgroup><col class="time-col">${cols.map(()=>'<col class="slot-col">').join('')}</colgroup><thead><tr><th rowspan="3">時間</th>${stores.map(([store,n])=>`<th class="store-head ${storeClass(store)}" colspan="${n}">${store}</th>`).join('')}</tr><tr>${heads.map(g=>`<th class="${storeClass(g.store)} gstart" ${g.cols.length>1?`colspan="${g.cols.length}"`:'rowspan="2"'} title="${esc(roleNote(g.role,g.count))}">${headLabel(g)}</th>`).join('')}</tr><tr>${heads.filter(g=>g.cols.length>1).flatMap(g=>g.cols.map(c=>`<th class="num ${storeClass(c.store)} ${c.gstart?'gstart':''}">${posLabel(c.role,c.occ)}${posTag(c.store,c.role,c.occ)}</th>`)).join('')}</tr></thead><tbody>${hours.map(hour=>`<tr class="${hour.endsWith(':00')?'hour':'half'}"><th title="${hour}–${plusSlot(hour)}">${hour.endsWith(':00')?hour:`<small>${hour}</small>`}${carCell(hour)}</th>${cols.map(c=>{const slot=slotAt.get(`${c.store}|${c.role}|${hour}`),cls=`${storeClass(c.store)} ${c.gstart?'gstart':''}`;if(!slot||c.occ>=(Number(slot.count)||0))return `<td class="na ${cls}"${slot?` data-open-counts="${slot.id}" title="この時間は不要（クリックで必要人数を設定）"`:''}></td>`;const item={...slot,occ:c.occ,key:`${slot.id}-${c.occ}`};return `<td class="${cls}${state.assignments[item.key]?'':' open'}">${slotItemHtml(item,audit)}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function render(){renderShiftGrid();renderAvailabilityBoard();renderMembers();renderRoleRules();updateStats();renderView();if(!$('#countDrawer').contains(document.activeElement))renderCountEditor();window.onStateChange?.();}
const dataViews=['availability','members','shift'];
function renderView(){const has=state.availability.length>0;if(!has&&dataViews.includes(state.view))state.view='import';document.body.dataset.view=state.view;document.querySelectorAll('main>[data-view]').forEach(el=>el.classList.toggle('hidden',el.dataset.view!==state.view));document.querySelectorAll('.tab').forEach(b=>{const t=b.dataset.tab,on=t===state.view;b.disabled=!has&&dataViews.includes(t);b.title=b.disabled?'CSVを読み込むと使えます':'';b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));});}
const showView=view=>{state.view=view;renderView();window.scrollTo(0,0);stickGridHead();};
function pruneAssignments(){const items=new Map(flattened().map(x=>[x.key,x]));let removed=0;for(const [key,name] of Object.entries(state.assignments)){if(!name)continue;const item=items.get(key);if(!item||!fitsSlot(name,item)){delete state.assignments[key];removed++;}}if(removed)showToast(`条件に合わなくなった ${removed} 枠の割当を外しました`);}
function addSlot(s){const defaultDate=[...new Set(state.availability.map(a=>a.date))].sort()[0]||new Date().toISOString().slice(0,10);const slot={date:defaultDate,store:'',role:'',start:'09:00',count:1,...s};slot.end=plusSlot(slot.start);state.slots.push({...slot,id:uid()});render();}
const eventDates=()=>[...new Set(state.availability.map(a=>a.date))].sort().slice(0,3);
function migrateHalfHours(){if(state.settings.slotMinutes===SLOT)return;const byId={};for(const date of eventDates())for(const [store,roles] of Object.entries(rolesForDate(date)))for(const [role] of roles)for(let h=0;h<24;h++){const start=`${String(h).padStart(2,'0')}:00`;byId[slotId(date,store,role,start)]={date,store,role,half:slotId(date,store,role,`${String(h).padStart(2,'0')}:30`)};}const has=m=>Object.keys(state[m]).length>0;if(['assignments','slotTypes','slotBlanks','slotCounts'].some(has)){for(const m of ['assignments','slotTypes','slotBlanks'])for(const [k,v] of Object.entries({...state[m]})){const i=k.lastIndexOf('-'),info=byId[k.slice(0,i)];if(!info)continue;const target=`${info.half}-${k.slice(i+1)}`;if(state[m][target]===undefined||state[m][target]==='')state[m][target]=v;}for(const [id,v] of Object.entries({...state.slotCounts}))if(byId[id]&&state.slotCounts[byId[id].half]===undefined)state.slotCounts[byId[id].half]=v;}state.settings.slotMinutes=SLOT;state.slots=[];}
function ensureAllSlots(){migrateHalfHours();migratePositions();eventDates().forEach(date=>ensureGridSlots(date,hoursForDate(date)));migrateBlanks();}
// 旧「ドリッパー上級生（2）」＋「ドリッパー（下級生＋上級生）（4）」を「ドリッパー」1st〜6th にまとめる（上級生の枠は 1st と最後へ）。あわせて未合格の人のアイスを × に
const OLD_DRIP=['ドリッパー上級生','ドリッパー（下級生＋上級生）'];
function migratePositions(){if(state.settings.positions)return;const rr=state.roleRequirements,k=r=>ruleKey('本店',r),top=rr[k(OLD_DRIP[0])]||'上級生';rr[k('ドリッパー')]??=rr[k(OLD_DRIP[1])]||'1年目合格';for(const date of eventDates())for(let m=0;m<24*60;m+=SLOT){const start=toHM(m),[sup,mix]=OLD_DRIP.map(r=>slotId(date,'本店',r,start)),id=slotId(date,'本店','ドリッパー',start),sc=state.slotCounts[sup]??2,mc=state.slotCounts[mix]??4;const order=[...(sc?[[sup,0]]:[]),...Array.from({length:mc},(_,i)=>[mix,i]),...Array.from({length:Math.max(0,sc-1)},(_,i)=>[sup,i+1])];for(const map of ['assignments','slotTypes'])order.forEach(([old,i],p)=>{const v=state[map][`${old}-${i}`];if(v!==undefined&&!state[map][`${id}-${p}`])state[map][`${id}-${p}`]=v;delete state[map][`${old}-${i}`];});if((sup in state.slotCounts||mix in state.slotCounts)&&!(id in state.slotCounts)&&sc+mc!==6)state.slotCounts[id]=sc+mc;delete state.slotCounts[sup];delete state.slotCounts[mix];}rr[posKey('本店','ドリッパー',0)]??=top;rr[posKey('本店','ドリッパー',5)]??=top;OLD_DRIP.forEach(r=>delete rr[k(r)]);for(const [name,st] of Object.entries(state.memberStatuses))if(st==='未合格')state.memberDrips[name]=dripsForIce('×');state.settings.positions=1;state.slots=[];}
function migrateBlanks(){const keys=Object.keys(state.slotBlanks);if(!keys.length)return;const bySlot={};for(const k of keys){const i=k.lastIndexOf('-');if(!state.assignments[k])(bySlot[k.slice(0,i)]??=new Set()).add(Number(k.slice(i+1)));}for(const [id,blank] of Object.entries(bySlot)){const slot=state.slots.find(s=>s.id===id);if(!slot)continue;const keep=Array.from({length:Number(slot.count)||0},(_,i)=>i).filter(i=>!blank.has(i)),moved=keep.map(i=>[state.assignments[`${id}-${i}`],slotChoices[slot.role]?slotType({role:slot.role,key:`${id}-${i}`,occ:i}):undefined]);for(let i=0;i<(Number(slot.count)||0);i++){delete state.assignments[`${id}-${i}`];delete state.slotTypes[`${id}-${i}`];}moved.forEach(([a,t],i)=>{if(a)state.assignments[`${id}-${i}`]=a;if(t!==undefined)state.slotTypes[`${id}-${i}`]=t;});setSlotCount(slot,keep.length);}state.slotBlanks={};}
function autoAssign(){const workload={},booked={};state.assignments={};ensureAllSlots();const free=(name,x)=>!(booked[name]||[]).some(b=>b.date===x.date&&x.start<b.end&&b.start<x.end);
// 次の枠（同じ役職・同じ番目を優先）にも続けて入れられるか
const pairOf=(x,name)=>{const occs=slotAtOffset(x,1);return [occs[x.occ],...occs].find(y=>y&&!decided(y.key)&&free(name,y)&&available(y).some(a=>a.name===name));};
// 条件の厳しい番目（上級生枠など）から先に埋め、ほかの番目ではその条件を満たす人をなるべく温存する
const lv=x=>statusLevels[requiredFor(x)],items=flattened().sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)||lv(b)-lv(a));
for(const x of items){if(decided(x.key))continue;const candidates=[...new Map(available(x).filter(a=>free(a.name,x)).map(a=>[a.name,a])).values()];const strict=Math.max(0,...Array.from({length:Number(x.count)||0},(_,i)=>lv({...x,occ:i}))),spare=a=>strict>lv(x)&&levelOf(a.name)>=strict;const pairs=new Map(candidates.map(a=>[a.name,pairOf(x,a.name)]));const score=a=>(workload[a.name]||0)-(wants(a.name,x.role)?1:0);candidates.sort((a,b)=>spare(a)-spare(b)||!!pairs.get(b.name)-!!pairs.get(a.name)||dislikes(a.name,x.role)-dislikes(b.name,x.role)||score(a)-score(b));const c=candidates[0];if(!c)continue;for(const t of [x,pairs.get(c.name)].filter(Boolean)){state.assignments[t.key]=c.name;(booked[c.name]??=[]).push(t);workload[c.name]=(workload[c.name]||0)+1;}}render();}
// 同じ役職の前（dir=-1）／次（dir=1）の枠の各番目
function slotAtOffset(item,dir){const start=dir>0?item.end:toHM(toMin(item.start)-SLOT);const slot=state.slots.find(s=>s.date===item.date&&s.store===item.store&&s.role===item.role&&s.start===start);return slot?Array.from({length:Math.max(0,Number(slot.count)||0)},(_,i)=>({...slot,occ:i,key:`${slot.id}-${i}`})):[];}
// 1時間のまとまりの相方（:00 の枠なら次、:30 の枠なら前）で、同じ人が入っている枠
function partnerOf(item,name){const dir=toMin(item.start)%60===0?1:-1,occs=slotAtOffset(item,dir),p=[occs[item.occ],...occs].find(x=>x&&state.assignments[x.key]===name);return p?{item:p,dir}:null;}
function download(name,text,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
const printName=n=>`<span class="s">${esc(shortNames[n]||n)}</span><span class="f">${esc(n)}</span>`;
const printRole={'店舗準備（本店）':'店舗準備（本店）','店舗準備（2号店）':'店舗準備（2号店）','店舗準備（くれあ）':'店舗準備（くれあ）','実委からの受け取り':'受け取り'};
function printDayTable(date){const hours=hoursForDate(date),carCell=carCellFor(date),find=(store,role,h)=>state.slots.find(s=>s.date===date&&s.store===store&&s.role===role&&s.start===h);const groups=Object.entries(rolesForDate(date)),cols=[];for(const [store,roles] of groups)for(const [role] of roles){const max=Math.max(0,...hours.map(h=>Number(find(store,role,h)?.count)||0));for(let i=0;i<max;i++){cols.push({store,role,i,first:!cols.length||cols[cols.length-1].store!==store});}}if(!cols.length)return '<p class="meta">必要な枠がありません。</p>';const heads=groups.map(([store])=>[store,cols.filter(c=>c.store===store).length]).filter(([,n])=>n);const roleGroups=[];cols.forEach(c=>{const g=roleGroups[roleGroups.length-1];if(g&&g.store===c.store&&roleBase(g.role)===roleBase(c.role))g.cols.push(c);else roleGroups.push({store:c.store,role:c.role,first:c.first,cols:[c]});});return `<table class="grid ${cols.length>22?'dense':''}" style="--rowh:${Math.min(10,Math.floor(140/Math.max(1,hours.length)*10)/10)}mm"><colgroup><col class="tc">${cols.map(()=>'<col>').join('')}</colgroup><thead><tr><th rowspan="3" class="time">時間</th>${heads.map(([store,n])=>`<th colspan="${n}" class="first ${storeClass(store)}">${esc(store)}</th>`).join('')}</tr><tr>${roleGroups.map(g=>`<th class="${g.first?'first':''} ${storeClass(g.store)} role" ${g.cols.length>1?`colspan="${g.cols.length}"`:'rowspan="2"'}>${esc(roleBase(g.role)==='ドリッパー'?'ドリッパー':printRole[g.role]||g.role)}</th>`).join('')}</tr><tr>${roleGroups.filter(g=>g.cols.length>1).flatMap(g=>g.cols.map((c,n)=>`<th class="num ${c.first?'first':''} ${storeClass(c.store)} role">${posLabel(c.role,c.i)}${posTag(c.store,c.role,c.i)}</th>`)).join('')}</tr></thead><tbody>${hours.map((h,r)=>`<tr class="${h.endsWith(':00')?'hour':''} ${Number(h.slice(0,2))%2?'band':''}"><th class="time">${h.endsWith(':00')?h:`<small>${h}</small>`}${carCell(h)}</th>${cols.map(c=>{const sl=find(c.store,c.role,h),cls=c.first?'first':'';if(!sl||c.i>=sl.count)return `<td class="na ${cls}"></td>`;const key=`${sl.id}-${c.i}`,n=state.assignments[key];return `<td class="${n?'':'open'} ${cls}">${n?printName(n)+(slotChoices[c.role]?dripBadge(n):''):''}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
// 印刷の個人別シフト（列：メンバー、行：時間）。1ページに収まるよう人数を均等に分ける
function personSheets(date,title,audit,head,cls=''){const names=namesOn(date),n=Math.ceil(names.length/22),size=Math.ceil(names.length/Math.max(1,n)),pages=[];for(let i=0;i<names.length;i+=size)pages.push(names.slice(i,i+size));const rowh=Math.min(9,Math.floor(165/Math.max(1,hoursForDate(date).length)*10)/10);return pages.map((list,p)=>`<div class="sheet ${cls}">${head(`${title}${pages.length>1?`（${p+1}/${pages.length}）`:''}`,'列：メンバー ／ 行：時間　色＝担当（<b class="key store-main">本店</b><b class="key store-second">2号店</b><b class="key store-kurea">くれあ</b><b class="key store-clean">美化</b><b class="key store-prep">準備</b>）　灰色＝参加できない時間　空欄＝担当なし<br>勤務時間に昼食・休憩は含みません')}${personMatrixHtml(date,list,audit,n=>shortNames[n]||n).replace('<table class="pm">',`<table class="pm" style="--rowh:${rowh}mm">`)}</div>`).join('');}
function personSegments(name,date){const items=flattened().filter(x=>x.date===date&&state.assignments[x.key]===name).sort((a,b)=>a.start.localeCompare(b.start));const label=x=>`${storeNames.includes(x.store)?`${x.store}・`:''}${x.role}${ordinalRoles.includes(x.role)?` ${posLabel(x.role,x.occ)}`:''}`;const segs=[];for(const x of items){const last=segs[segs.length-1];if(last&&last.end===x.start&&last.label===label(x))last.end=x.end;else segs.push({start:x.start,end:x.end,label:label(x)});}return segs;}
