function moveAssignment(from,to){if(!from||!to||from===to)return;const before=snapshotAssignments(),items=new Map(flattened().map(x=>[x.key,x]));const src=items.get(from),dst=items.get(to),name=state.assignments[from];if(!src||!dst||!name)return;const other=state.assignments[to]||'',partner=!other&&partnerOf(src,name);if(partner){const ignore=[from,partner.item.key,to];state.assignments[from]='';state.assignments[partner.item.key]='';const occs=slotAtOffset(dst,partner.dir),dp=[occs[dst.occ],...occs].find(x=>x&&x.key!==to&&(!decided(x.key)||x.key===partner.item.key)&&canTake(name,x,[...ignore,x.key]));if(dp&&canTake(name,dst,[...ignore,dp.key])){for(const k of [to,dp.key])state.assignments[k]=name;const [a,b]=partner.dir>0?[dst,dp]:[dp,dst];return finishChange(before,`${name} を ${a.start}〜${b.end} ${itemLabel(dst)} に移動しました`);}state.assignments[from]=name;state.assignments[partner.item.key]=name;}state.assignments[from]='';state.assignments[to]='';if(!canTake(name,dst,[from,to])){state.assignments[from]=name;state.assignments[to]=other;render();return showToast(`${name} は移動先の条件を満たさないか、同じ時間に別の枠に入っているため移動できません`);}state.assignments[to]=name;let message=`${name} を ${slotLabel(dst)} に移動しました`;if(other){if(canTake(other,src,[from,to])){state.assignments[from]=other;message=`${name} と ${other} を入れ替えました`;}else message+=`（${other} は元の枠に入れないため未割当にしました）`;}finishChange(before,message);}
