const canTake=(name,item,ignore)=>available(item).some(a=>a.name===name)&&!busyElsewhere(name,item,ignore);
let movingKey=null;
function markTargets(fromKey){const name=state.assignments[fromKey],all=flattened(),items=new Map(all.map(x=>[x.key,x]));const mine=all.filter(x=>x.key!==fromKey&&state.assignments[x.key]===name);document.querySelectorAll('#shiftGridWrap .slot').forEach(el=>{const key=el.dataset.slotKey,item=items.get(key);if(key===fromKey)return el.classList.add('drag-source');if(!item||state.assignments[key]===name||mine.some(x=>x.key!==key&&x.date===item.date&&x.start<item.end&&item.start<x.end))return;if(available(item).some(a=>a.name===name))el.classList.add('drop-ok');});}
function clearTargets(){movingKey=null;document.body.classList.remove('dragging','moving');document.querySelectorAll('.drop-ok,.drop-hover,.drag-source').forEach(el=>el.classList.remove('drop-ok','drop-hover','drag-source'));}
// ---- 担当者の選択（ポップアップ）----
const statusShort={'上級生':'上級','2年目合格':'2年','1年目合格':'1年','未合格':'未合格'};
const itemLabel=x=>`${storeNames.includes(x.store)?`${x.store}・`:''}${x.role}${Number(x.count)>1&&x.occ!==undefined?` ${posLabel(x.role,x.occ)}`:''}`;
const overlapping=(name,item,ignore)=>flattened().filter(x=>!ignore.includes(x.key)&&state.assignments[x.key]===name&&x.date===item.date&&x.start<item.end&&item.start<x.end);
const coarse=matchMedia('(pointer:coarse)').matches;
let picker=null,pickRun=60/SLOT;// 何枠続けて入れるか（標準1時間。Infinity＝入れられる限り）
// 「続けて入れる」：同じ店舗・役職の次の時間帯に、空き・条件・重複なしで入れる限り続けて割り当てる
function runTargets(item,name,limit=Infinity){const out=[item];let cur=item;while(out.length<limit){const slot=state.slots.find(s=>s.date===cur.date&&s.store===cur.store&&s.role===cur.role&&s.start===cur.end);if(!slot)break;const occs=Array.from({length:Math.max(0,Number(slot.count)||0)},(_,i)=>({...slot,occ:i,key:`${slot.id}-${i}`}));const already=occs.find(x=>state.assignments[x.key]===name);if(already){cur=already;continue;}const next=[occs[cur.occ],...occs].find(x=>x&&!decided(x.key)&&available(x).some(a=>a.name===name)&&!busyElsewhere(name,x,[]));if(!next)break;out.push(next);cur=next;}return out;}
function pickerCandidates(item){const audit=assignmentAudit(),chosen=state.assignments[item.key]||'',q=picker.q.normalize('NFKC').replace(/\s/g,'');const names=[...new Set(available(item).map(a=>a.name))].filter(n=>n!==chosen&&(!q||n.normalize('NFKC').replace(/\s/g,'').includes(q)));const list=names.map(name=>({name,busyAt:overlapping(name,item,[item.key]),hours:audit.hours[name]?.[item.date]||0,windows:state.availability.filter(a=>a.name===name&&a.date===item.date).map(a=>`${a.start}–${a.end}`).join('、')}));const order=(a,b)=>wants(b.name,item.role)-wants(a.name,item.role)||dislikes(a.name,item.role)-dislikes(b.name,item.role)||a.hours-b.hours||a.name.localeCompare(b.name,'ja');return {free:list.filter(x=>!x.busyAt.length).sort(order),busy:list.filter(x=>x.busyAt.length).sort(order)};}
function pickerRowHtml(c,item,i){const busy=c.busyAt.length>0,run=pickRun>1&&!busy?runTargets(item,c.name,pickRun):null;const mark=wants(c.name,item.role)?'<i class="want">★</i>':dislikes(c.name,item.role)?'<i class="dislike">△</i>':'';const st=state.memberStatuses[c.name];return `<button type="button" class="pk-item ${busy?'busy':''} ${i===picker.active?'active':''}" data-pk-name="${esc(c.name)}" data-i="${i}"><span class="pk-line"><span class="pk-name">${mark}${esc(c.name)}</span>${slotChoices[item.role]?dripBadge(c.name):''}${statusShort[st]?`<span class="pk-status">${statusShort[st]}</span>`:''}<span class="pk-hours" title="この日の勤務時間">${fmt(c.hours)}</span></span><span class="pk-meta">${busy?`<b>${esc(c.busyAt.map(x=>`${x.start}〜 ${itemLabel(x)}`).join('、'))}</b> で勤務中 → こちらへ移動`:`参加 ${esc(c.windows)}${run?`<b class="pk-run-to ${run.length<pickRun&&pickRun!==Infinity?'short':''}">→ ${run[run.length-1].end} まで ${run.length*SLOT/60}時間</b>`:''}`}</span></button>`;}
function renderPickerList(){const box=$('#pkList');if(!box||!picker)return;const item=flattened().find(x=>x.key===picker.key);if(!item)return closePicker();const {free,busy}=pickerCandidates(item),all=[...free,...busy];picker.names=all.map(c=>c.name);picker.active=Math.min(picker.active,Math.max(0,all.length-1));box.innerHTML=all.length?`${free.length?`<div class="pk-sec">空いている人 <em>${free.length}</em></div>${free.map((c,i)=>pickerRowHtml(c,item,i)).join('')}`:''}${busy.length?`<div class="pk-sec">別の枠で勤務中 <em>${busy.length}</em></div>${busy.map((c,i)=>pickerRowHtml(c,item,free.length+i)).join('')}`:''}`:`<p class="pk-empty">${picker.q?'該当するメンバーがいません':'この時間・役職の条件に合うメンバーがいません。<br><small>勤務可能時間・所属店舗・ステータス・ドリップ種類で絞り込んでいます。</small>'}</p>`;box.querySelector('.pk-item.active')?.scrollIntoView({block:'nearest'});}
function openPicker(key,anchor){const item=flattened().find(x=>x.key===key);if(!item)return;clearTargets();hideToast();picker={key,q:'',active:0,names:[]};document.body.classList.add('picking');const chosen=state.assignments[key]||'',el=$('#picker');el.innerHTML=`<div class="pk-head"><div><strong>${esc(itemLabel(item))}</strong><small>${esc(dayName(item.date,eventDates().indexOf(item.date)))} ${item.start}–${item.end}${(r=>r==='未設定'?'':`・${r==='上級生'?'上級生のみ':`${r}以上`}`)(requiredFor(item))}</small></div><button type="button" class="pk-close" data-pk-close title="閉じる（Esc）">×</button></div>${chosen?`<div class="pk-current"><span>現在 <b>${esc(chosen)}</b></span><button type="button" class="quiet small" data-pk-move>移動…</button><button type="button" class="quiet small danger" data-pk-clear>外す</button></div>`:''}<div class="pk-tools"><input type="search" id="pkSearch" placeholder="名前で絞り込み" autocomplete="off"></div><div class="pk-runs" title="同じ役職の次の枠にも続けて割り当てます（標準1時間。空き・条件・重複がある枠で止まります）"><span>長さ</span>${[[1,'30分'],[2,'1時間'],[3,'1.5時間'],[4,'2時間'],[Infinity,'最大']].map(([n,l])=>`<button type="button" class="${n===pickRun?'on':''}" data-pk-run="${n}">${l}</button>`).join('')}</div><div id="pkList" class="pk-list"></div>`;el.classList.remove('hidden');anchor.classList.add('pk-open');renderPickerList();placePicker(el,anchor);if(!coarse)$('#pkSearch').focus();}
// セルの下に出す。入らなければ上、どちらにも入らなければ広いほうに出して高さを縮める（セル自体は隠さない）
function placePicker(el,anchor){el.style.maxHeight='';if(innerWidth<=640)return;const r=anchor.getBoundingClientRect(),w=el.offsetWidth,h=el.offsetHeight,below=innerHeight-r.bottom-12,above=r.top-12,down=h<=below||(h>above&&below>=above);if(h>(down?below:above))el.style.maxHeight=`${Math.max(160,down?below:above)}px`;el.style.left=`${Math.min(Math.max(8,r.left),innerWidth-w-8)}px`;el.style.top=`${down?r.bottom+4:Math.max(8,r.top-4-el.offsetHeight)}px`;}
function closePicker(){if(!picker)return;picker=null;document.querySelectorAll('.pk-open').forEach(x=>x.classList.remove('pk-open'));document.body.classList.remove('picking');$('#picker').classList.add('hidden');}
function pickName(name){const key=picker.key,item=flattened().find(x=>x.key===key);if(!item)return closePicker();const busyAt=overlapping(name,item,[key]),targets=busyAt.length?[item]:runTargets(item,name,pickRun);closePicker();const before=snapshotAssignments();busyAt.forEach(x=>state.assignments[x.key]='');targets.forEach(x=>state.assignments[x.key]=name);finishChange(before,busyAt.length?`${name} を ${busyAt.map(itemLabel).join('、')} から ${itemLabel(item)} へ移動しました`:`${name} を ${item.start}〜${targets[targets.length-1].end} ${itemLabel(item)} に割り当てました`);}
$('#picker').addEventListener('click',e=>{if(!picker)return;const t=e.target;if(t.closest('[data-pk-close]'))return closePicker();const runBtn=t.closest('[data-pk-run]');if(runBtn){pickRun=Number(runBtn.dataset.pkRun);runBtn.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b===runBtn));return renderPickerList();}const key=picker.key,name=state.assignments[key];if(t.closest('[data-pk-clear]')){closePicker();const before=snapshotAssignments();state.assignments[key]='';return finishChange(before,`${name} を外しました`);}if(t.closest('[data-pk-move]')){closePicker();movingKey=key;document.body.classList.add('moving');markTargets(key);return showToast(`${name} を移動中：緑の枠をクリックで移動・入れ替え（Escで取消）`,true);}const row=t.closest('.pk-item');if(row)pickName(row.dataset.pkName);});
