let lastChange=null;
const undoMaps=['assignments'];
const snapshotAssignments=()=>Object.fromEntries(undoMaps.map(m=>[m,{...state[m]}]));
function finishChange(before,message){const changed=[];for(const m of undoMaps)for(const k of new Set([...Object.keys(before[m]),...Object.keys(state[m])]))if((before[m][k]||'')!==(state[m][k]||''))changed.push([m,k,before[m][k]||'',state[m][k]||'']);render();if(!changed.length)return;lastChange=changed;showToast(message,false,{label:'元に戻す',fn:undoLastChange});}
function undoLastChange(){const c=lastChange;lastChange=null;if(!c)return;let skipped=0;for(const [m,k,prev,next] of c){if((state[m][k]||'')!==next){skipped++;continue;}state[m][k]=prev;}render();showToast(skipped?`元に戻しました（その後に変更された ${skipped} 枠はそのままです）`:'元に戻しました');}
