let press=null,drag=null,suppressClick=false;
$('#shiftGridWrap').addEventListener('pointerdown',e=>{const btn=e.target.closest('.slot.has-person [data-pick-slot]');if(!btn||e.button>0||document.body.classList.contains('moving'))return;if(e.pointerType==='mouse')e.preventDefault();press={key:btn.dataset.pickSlot,id:e.pointerId,x:e.clientX,y:e.clientY,touch:e.pointerType!=='mouse',timer:null};if(press.touch)press.timer=setTimeout(()=>{if(press)startDrag(press.x,press.y);},350);});
window.addEventListener('pointermove',e=>{if(drag){drag.x=e.clientX;drag.y=e.clientY;moveDrag();return;}if(!press||e.pointerId!==press.id)return;const d=Math.hypot(e.clientX-press.x,e.clientY-press.y);if(press.touch){if(d>8){clearTimeout(press.timer);press=null;}return;}if(d>5)startDrag(e.clientX,e.clientY);});
