function autoScroll(){if(!drag)return;const wrap=$('#shiftGridWrap'),r=wrap.getBoundingClientRect(),edge=56,speed=d=>Math.ceil((edge-d)/4);const {x,y}=drag;let dx=0,dy=0;if(x<r.left+edge)dx=-speed(x-r.left);else if(x>r.right-edge)dx=speed(r.right-x);if(y<r.top+edge)dy=-speed(y-r.top);else if(y>r.bottom-edge)dy=speed(r.bottom-y);if(dx||dy){wrap.scrollBy(dx,dy);hoverTarget();}const top=$('.tabbar').getBoundingClientRect().bottom;if(y<top+30)scrollBy(0,-12);else if(y>innerHeight-30)scrollBy(0,12);drag.raf=requestAnimationFrame(autoScroll);}
