const sampleStatus=i=>i%10<3?'上級生':i%10<5?'2年目合格':i%10<8?'1年目合格':'未合格';
const sampleStores=i=>i<20?['本店']:i<30?['2号店']:i<40?['くれあ']:i<45?['本店','2号店']:['本店','くれあ'];
const sampleIce=i=>!sampleStores(i).includes('本店')?'':sampleStatus(i)==='未合格'?'×':['○','1杯のみ','×','2杯のみ'][i%4];
const sampleWants=i=>[['ドリッパー'],['レジ','ホール'],[],['提供'],['調理'],[]][i%6];
const sampleDislikes=i=>[[],['マスター'],[],['レジ'],[],[],['ホール']][i%7];
const csvLine=row=>row.map(v=>/[",\n]/.test(v)?`"${String(v).replaceAll('"','""')}"`:v).join(',');
function sampleCsv(){const hh=h=>`${String(h).padStart(2,'0')}:00`;const rows=[['氏名','ステータス','所属店舗','アイス（○／1杯のみ／2杯のみ／×）','車の有無','やりたい役職','苦手な役職','日付','開始時刻','終了時刻']];sampleNames.forEach((name,i)=>sampleDates.forEach((date,day)=>{const start=10+(i*3+day*2)%5,end=Math.min(20,start+5+(i+day)%5);rows.push([name,sampleStatus(i),sampleStores(i).join(', '),sampleIce(i),i%5===0?'あり':'なし',sampleWants(i).join(', '),sampleDislikes(i).join(', '),date,hh(start),hh(end)]);}));return '\ufeff'+rows.map(csvLine).join('\n');}
$('#sampleBtn').onclick=()=>{if(!importAllowed())return;state.slots=[];state.slotTypes={};state.slotCounts={};state.slotBlanks={};state.gridDate='';importCSV(sampleCsv(),'50名・3日間（10/30 前日準備、10/31・11/1 本番）のサンプルを読み込みました。ステータス・所属店舗・対応ドリップ・車の有無・役職の希望もCSVから反映しています。');};
$('#sampleDataBtn').onclick=()=>download('survey_sample_50members.csv',sampleCsv());
render();
